a.lazytime:
__ht__function() {
    data.s('2d.visible', function (data) {
        let isVisible = data.a('status') !== 'hidden';

        if (isVisible) {
            // 先清除可能存在的定时器，防止重复触发
            clearTimeout(data.a('hideTimeout'));

            // 10秒后自动隐藏
            let timeoutId = setTimeout(() => {
                data.a('status', 'hidden'); // 修改 status，触发可见性变化
                data.a('hideTimeout', null); // 计时器执行完后清除标记
            }, 10000);

            // 存储定时器 ID，防止重复触发
            data.a('hideTimeout', timeoutId);
        }

        return isVisible;
    });

    // 触发状态变化
    data.a('status', 'normal'); // 让图标开始显示，10秒后隐藏
}

a.2dVisible:
__ht__function() {
    // 绑定 2d.visible 控制图标可见性
    data.s('2d.visible', function (data) {
        let isVisible = data.a('status') !== false;

        if (isVisible) {
            // 先清除可能存在的定时器，防止重复触发
            clearTimeout(data.a('hideTimeout'));

            let timeoutId = setTimeout(() => {
                data.a('status', false); 
                data.a('hideTimeout', null);
            }, 1000);

            // 存储定时器 ID，防止重复触发
            data.a('hideTimeout', timeoutId);
        }

        return isVisible;
    });

    // 点击事件：当点击某个元素时触发图标显示
    data.on('click', function() {
        data.a('status', false);
    });
}

