let Line = "B101";
let Area = "1"
let Processes = "加热炉";
let SHIFT_GROUP = group.a('group');
var row1 = graphView.dm().getDataByTag('钢坯号');
var row2 = graphView.dm().getDataByTag('异常类型');
var row3 = graphView.dm().getDataByTag('位置');
