var row7 = graphView.dm().getDataByTag('确认人');
var row8 = graphView.dm().getDataByTag('采集重量');
console.log(row6.a('ht.value'))
let SlabNo = row1.a('ht.value');
let AbnormalType = row2.a('ht.value');
let Section = row3.a('ht.value');
let ActValue = row4.a('ht.value');
let RequireValue = row5.a('ht.value');
let OccurTime = row6.a('ht.value');
let Confirmer = row7.a('ht.value');
let Weight = row8.a('ht.value');
let url = `http://180.10.10.12:9003/api/sdf/sltdatabnormal/boardcreate`;
    // 准备请求数据
const requestData = {
    "line" : Line,
    "Area" : Area,
    "Processes" : Processes,
    "SHIFT_GROUP" : SHIFT_GROUP,
    "ROLL_PLAN_NO": "0",
    "MtlNo": SlabNo.toString(),
