    "Section": Section.toString(),
    "ActValue": parseFloat(ActValue),
    "Weight": parseFloat(Weight),
    "RequireValue": parseFloat(RequireValue).toString(), // ✅
    "OccurTime": new Date(OccurTime).toISOString(), // ✅ ISO格式
    "Confirmer": Confirmer.toString()
};

