.then(response => {
  if (!response.ok) throw new Error(`HTTP错误! 状态码: ${response.status}`);
  return response.json(); // 解析响应数据（如果返回JSON）
})
.then(data => {
  console.log('PUT请求成功:', data);
  if (data.Message) {
    showToast(data.Message);
  }
})
.catch(error => {
  console.error('PUT请求失败:', error);
  showToast('请求失败，请稍后重试');
});}

